
# --- portable paths (generated by export) -------------------------
# Everything below derives from the repo location; override with env vars
#   COMFYUI_DIR / COMFY_PYTHON / FOUNDRY_PYTHON
$FF_ROOT = if ($PSScriptRoot -and (Test-Path (Join-Path $PSScriptRoot 'app.py'))) {
    $PSScriptRoot
} else {
    Split-Path -Parent $PSScriptRoot
}
$FF_COMFY = if ($env:COMFYUI_DIR) { $env:COMFYUI_DIR } else { Join-Path (Split-Path -Parent $FF_ROOT) 'ComfyUI' }
$FF_COMFY_PY = if ($env:COMFY_PYTHON) { $env:COMFY_PYTHON } else { Join-Path $FF_COMFY 'python.exe' }
$FF_APP_PY = if ($env:FOUNDRY_PYTHON) { $env:FOUNDRY_PYTHON } else { 'python' }
$FF_LOG = Join-Path $FF_ROOT 'logs'
if (-not (Test-Path $FF_LOG)) { New-Item -ItemType Directory -Force -Path $FF_LOG | Out-Null }
# ------------------------------------------------------------------
# start-cpu-llm.ps1 - 启动纯 CPU 大模型服务（Qwen3.6-35B-A3B Q6_K, -ngl 0）
# 2026-08-20 宇凯要求：CPU 跑大模型，精度优先（Q6_K 近无损）、速度可低，不占 GPU
# 端口 8082（GPU 实例 8080 / 废弃 8081 之外）；与 ComfyUI 双实例并行互不干扰
# 96 线程实测与 48 线程同速（内存带宽瓶颈）→ 用 48 线程留一半核给系统/ComfyUI
# 用法：powershell -ExecutionPolicy Bypass -File start-cpu-llm.ps1
$ErrorActionPreference = "Continue"
$port = 8082
$logDir = $FF_LOG
New-Item -ItemType Directory -Force -Path $logDir | Out-Null

function Test-Port($p) {
    return [bool](Get-NetTCPConnection -LocalPort $p -State Listen -ErrorAction SilentlyContinue)
}

if (Test-Port $port) {
    Write-Host "CPU llama-server already running (port $port)" -ForegroundColor Green
} else {
    Write-Host "Starting CPU llama-server (Qwen3.6-35B-A3B UD-Q6_K, -ngl 0, threads 48)..." -ForegroundColor Yellow
    $ts = Get-Date -Format 'yyyyMMdd-HHmmss'
    Start-Process -FilePath 'D:\ollama-models\_download\llama-cpp\llama-server.exe' `
        -ArgumentList '-m','D:\ollama-models\_download\Qwen3.6-35B-A3B-UD-Q6_K.gguf', `
            '-ngl','0','--threads','48','-c','32768','--flash-attn','on', `
            '--cache-type-k','q8_0','--cache-type-v','q8_0', `
            '--reasoning','off', `
            '--port',"$port",'--alias','qwen3.6-35b-cpu' `
        -WindowStyle Hidden `
        -RedirectStandardOutput (Join-Path $logDir "llama-cpu-$ts-out.log") `
        -RedirectStandardError (Join-Path $logDir "llama-cpu-$ts-err.log") | Out-Null
    $t = 0
    while (-not (Test-Port $port) -and $t -lt 300) { Start-Sleep -Seconds 3; $t += 3 }
    if (Test-Port $port) {
        Write-Host "CPU llama-server OK (${t}s) -> http://127.0.0.1:$port" -ForegroundColor Green
    } else {
        Write-Host "TIMEOUT, check $logDir\llama-cpu-$ts-err.log" -ForegroundColor Red
    }
}
